INSERT INTO spells (id, slug, school, level, title, title_ua, description, casting_time, duration, distance, components, material_description)
VALUES
  (320, 'friends', 'Зачарування', 0, 'Friends', 'Приязнь',
   'Доки заклинання триває, ти робиш з перевагою усі перевірки Харизми, спрямовані на одну вибрану тобою істоту, яка не ворожа по відношенню до тебе. Коли заклинання закінчується, істота розуміє, що ти впливав на її відношення за допомогою магії, і стає ворожою по відношенню до тебе. Істота, яка є схильною до насильства, може напасти на тебе. Інші можуть вимагати іншої відплати (вирішує Майстер), в залежності від відносин, які склалися між вами.',
   '1 дія', 'Концентрація, до 1 хвилини', 'На себе', '{verbal,material}'::component_type[],
   'невелика кількість гриму, що наноситься на обличчя при виконанні цього заклинання'),
  (321, 'searing-smite', 'Втілення', 1, 'Searing Smite', 'Полум’яна кара',
   E'Коли ти наступного разу попадеш по істоті атакою рукопашною зброєю, доки це заклинання триває, твоя зброя спалахує яскравим білим світлом, і атака заподіює цілі додатково 1к6 ушкоджень вогнем та підпалює її. Доки заклинання триває, ціль на початку кожного свого ходу повинна здійснювати кидок рятунку Статури. При провалі вона отримує 1к6 ушкоджень вогнем. При успіху заклинання закінчується.\nЯкщо ціль або істота, яка знаходиться в межах 5 футів від неї, витратить вчинок на гасіння полум’я, або якщо якийсь інший ефект погасив полум’я (наприклад, занурення в воду), заклинання теж закінчиться.\n**На вищих рівнях.** Якщо ти виконуєш це заклинання, витрачаючи магічний слот 2 рівня або вищого, то первинні додаткові ушкодження від атаки збільшуються на 1к6 за кожен рівень слота вище 1-го.',
   '1 бонусна дія', 'Концентрація, до 1 хвилини', 'На себе', '{verbal}'::component_type[], NULL),
  (322, 'thunderous-smite', 'Втілення', 1, 'Thunderous Smite', 'Громова кара',
   'В перший раз, коли ти попадаєш атакою рукопашною зброєю, доки це заклинання триває, твоя зброя видає громовий гуркіт, чутний з відстані 300 футів, і ця атака заподіює цілі додатково 2к6 ушкоджень звуком. Крім того, якщо ціль — істота, вона повинна зробити успішний кидок рятунку Сили, інакше вона буде відштовхнута на 10 футів від тебе і збита долілиць.',
   '1 бонусна дія', 'Концентрація, до 1 хвилини', 'На себе', '{verbal}'::component_type[], NULL)
ON CONFLICT (slug) DO NOTHING;

